function project(){return S.projects.find(p=>p.id===S.project)||S.projects[0]}
function access(p=project()){return p?.access||'admin'}
function canEdit(){return access()!=='viewer'}
function canManageAccounts(){return S.modeServer==='shared'&&S.user?.role==='admin'}
function getFields(p=project()){if(!p)return [];if(S.user?.role!=='admin'&&p.effectiveFields)return p.effectiveFields;const out={};[S.config.fields||[],S.config.teamFields?.[p.team]||[],p.fields||[]].forEach(layer=>layer.forEach(f=>{if(!out[f.id]?.locked)out[f.id]=f}));return Object.values(out)}
function fieldAllowed(f,op='visibility',role=access()){return role==='admin'||(f[op]||'everyone')==='everyone'||f[op]==='contributors'&&role==='contributor'}
async function saveProject(p,msg='Project saved'){const saved=await api('/api/projects/'+p.id,'PUT',p);S.projects=S.projects.map(x=>x.id===p.id?saved:x);if(msg)toast(msg);return saved}
async function reload(){const b=await api('/api/bootstrap');Object.assign(S,b);normalizePalette(S.config.palette);S.modeServer=S.mode;S.projects.forEach(ensureProjectLegends);if(!S.project||!S.projects.some(p=>p.id===S.project))S.project=S.projects[0]?.id;if(project()&&!S.country)S.country=project().country}
async function syncUpdates(){if(S.modeServer!=='shared'||!S.user||document.hidden||$('#overlay')?.children.length)return;try{const before=S.projects.map(p=>p.id+':'+p.version).sort().join('|'),b=await api('/api/bootstrap'),after=b.projects.map(p=>p.id+':'+p.version).sort().join('|');normalizePalette(b.config.palette);if(before===after&&JSON.stringify(S.config)===JSON.stringify(b.config)&&JSON.stringify(S.user)===JSON.stringify(b.user))return;Object.assign(S,b);normalizePalette(S.config.palette);S.modeServer=S.mode;S.projects.forEach(ensureProjectLegends);if(!S.projects.some(p=>p.id===S.project))S.project=S.projects[0]?.id;await render();toast('Workspace updated from the local server')}catch(e){if(e.status===401)login()}}
