function regionNames(g){return [...new Set(g.features.map(f=>f.properties.name))].sort((a,b)=>a.localeCompare(b))}
function propertyCity(r){return r?.district||r?.city||''}
function countryName(code){return code===WORLD?'World':continentView(code)?.name||S.countries.find(x=>x.code===code)?.name||code}
function mapKey(r,code=S.country){return continentView(code)?r.country+':'+r.state:code===WORLD?r.country:r.state}
