function filtered(){return (project()?.properties||[]).filter(r=>scopeIncludesCountry(S.country,r.country)&&(!S.state||r.state===S.state)&&(!S.district||propertyCity(r)===S.district)&&(!S.search||[r.name,r.code,countryName(r.country),r.state,propertyCity(r)].join(' ').toLowerCase().includes(S.search.toLowerCase())))}
function counts(){const c={};mapProperties().forEach(r=>{const key=mapKey(r);c[key]=(c[key]||0)+1});return c}
function header(eyebrow,title,subtitle,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${h(title)}</h1><p class="sub">${h(subtitle)}</p></div><div class="row">${actions}</div></div>`}
