function showTip(e,text){hideTip();const d=document.createElement('div');d.className='tooltip';d.setAttribute('aria-hidden','true');d.textContent=text;d.style.left=e.clientX+12+'px';d.style.top=e.clientY-35+'px';document.body.append(d)}function hideTip(){$$('.tooltip').forEach(x=>x.remove())}
async function selectRegion(name){if(continentView(S.country)&&name.includes(':')){const cut=name.indexOf(':');S.country=name.slice(0,cut);S.state=name.slice(cut+1)}else if(isCountryScope(S.country)){S.country=name;S.state=''} else S.state=S.state===name?'':name;S.district='';S.page=1;hideTip();await render()}
function propertyTable(rows){const world=isCountryScope(S.country),pages=Math.max(1,Math.ceil(rows.length/8));S.page=Math.min(Math.max(1,S.page),pages);const pageRows=rows.slice((S.page-1)*8,S.page*8),place=r=>world?countryName(r.country)+' / '+r.state:r.state;return `<section class="panel properties-panel"><div class="panelhead"><div class="row"><h2>${S.state?h(S.state)+' properties':'Property directory'}</h2><span class="badge">${rows.length}</span></div><div class="row"><div class="searchbox">${icon('search')}<input id="propertySearch" aria-label="Search properties" placeholder="Search properties…" value="${h(S.search)}"></div>${btn('CSV','csv','download','quiet small')}</div></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>PROPERTY NAME</th><th>PROPERTY CODE</th><th>${world?'COUNTRY / STATE':'STATE / PROVINCE'}</th><th>STATUS</th><th>TEAM</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${pageRows.map(r=>`<tr><td><strong>${h(r.name)}</strong></td><td>${h(r.code)}</td><td>${h(place(r))}</td><td><span class="status ${r.status==='Opportunity'?'opportunity':''}"><span class="live-dot" style="background:${project().palette[r.status]}"></span>${h(r.status)}</span></td><td>${h(r.team)}</td><td>${btn('', 'property',canEdit()?'edit':'visibility','quiet iconbtn',`data-id="${r.id}" aria-label="${canEdit()?'Edit':'View'} ${h(r.name)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>Showing ${(S.page-1)*8+1}–${Math.min(S.page*8,rows.length)} of ${rows.length} properties</span><div class="row">${btn('Previous','prev','','small',S.page<=1?'disabled':'')}<span>${S.page} / ${pages}</span>${btn('Next','next','','small',S.page>=pages?'disabled':'')}</div></div>`:`<div class="empty">${icon('location_on')}<h2>No properties here yet</h2><p>Add your first property or adjust the filters.</p></div>`}</section>`}
function projectsView(){const list=S.projects.filter(p=>!S.projectSearch||[p.name,p.team].join(' ').toLowerCase().includes(S.projectSearch.toLowerCase()));return header('YOUR WORKSPACE','A place for every project','Build a portfolio. Explore a market. Bring your teams together.',btn('New project','new-project','add','primary'))+`<div class="row between"><div class="row"><h2>All projects</h2><span class="badge">${S.projects.length}</span></div><div class="searchbox">${icon('search')}<input id="projectSearch" aria-label="Search projects" placeholder="Find a project…" value="${h(S.projectSearch||'')}"></div></div><div class="project-grid">${list.map(p=>`<article class="project-card"><div class="project-art"><svg data-card="${p.id}" role="img" aria-label="${h(p.name)} map preview"></svg><span class="badge">${h(p.team)}</span></div><div class="project-body"><h2>${h(p.name)}</h2><p>${h(p.description)}</p><div class="row caption">${icon('location_on')}${p.properties.length} properties <span>·</span>${new Set(p.properties.map(r=>r.country+':'+r.state)).size} regions</div><footer><span>${p.demo?'Sample project':h(access(p))+' access'}</span><span class="row">${access(p)==='admin'?btn('Settings','edit-project','edit','quiet small',`data-id="${p.id}"`):''}${btn('Open','open-project','arrow_forward','quiet small',`data-id="${p.id}"`)}</span></footer></div></article>`).join('')}<button class="new-card" data-action="new-project"><div><span class="plus-circle">${icon('add')}</span><h2>Start something new</h2><p>Create a project for your next big idea.</p></div></button></div>${exportsTable()}`}
async function drawCards(){for(const p of S.projects){await geo(p.country);drawMap($(`[data-card="${p.id}"]`),p.country,true,p)}}
function exportsTable(){const es=S.projects.flatMap(p=>p.exports.map(e=>({...e,project:p.name,projectId:p.id,canDelete:access(p)==='admin'}))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);return `<section class="panel properties-panel"><div class="panelhead"><h2>Recent exports</h2><span class="caption">Saved snapshots of your work</span></div>${es.length?`<div class="table-wrap"><table class="table"><thead><tr><th>FILE</th><th>PROJECT</th><th>EXPORTED</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${es.map(e=>`<tr><td><strong>${h(e.name)}</strong></td><td>${h(e.project)}</td><td>${date(e.date)}</td><td><span class="row">${btn('Download','download-export','download','quiet small',`data-id="${e.id}"`)}${e.canDelete?btn('Delete','delete-export','delete','quiet danger small',`data-id="${e.id}" data-project="${e.projectId}"`):''}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Your exports will live here</h2><p>Export a slide image or PDF report; each export is kept here.</p></div>'}</section>`}
function field(label,name,type='text',value='',required=false,extra=''){return `<label class="field ${type==='textarea'?'full':''}"><span>${h(label)}${required?' <span class="req" aria-hidden="true">*</span>':''}</span>${type==='textarea'?`<textarea name="${name}" ${required?'required':''} ${extra}>${h(value)}</textarea>`:`<input name="${name}" type="${type}" value="${h(value)}" ${required?'required':''} ${extra}>`}</label>`}
function usernameField(value=''){return `<label class="field"><span>Email username <span class="req" aria-hidden="true">*</span></span><span class="email-id"><input name="username" type="text" value="${h(value)}" required maxlength="64" autocomplete="username" aria-label="Email username"><span>@igt.com</span></span></label>`}
function selectField(label,name,opts,required=false,extra=''){return `<label class="field"><span>${h(label)}${required?' <span class="req" aria-hidden="true">*</span>':''}</span><select name="${name}" ${required?'required':''} ${extra}>${opts}</select></label>`}
function customInput(f,v='',disabled=false){const extra=disabled?'disabled':'';if(f.type==='checkbox')return `<label class="row"><input name="custom_${f.id}" type="checkbox" ${v?'checked':''} ${f.required?'required':''} ${extra}>${h(f.label)}${f.required?' *':''}</label>`;if(f.type==='select')return selectField(f.label,'custom_'+f.id,options(f.options||[],v,'Select…'),f.required,extra);return field(f.label,'custom_'+f.id,f.type,v,f.required,extra)}
function drawer(title,subtitle,body,footer='',wide=false,dialog=false){lastFocus=document.activeElement;$('#app').inert=true;$('#overlay').innerHTML=`<div class="overlay-backdrop" data-action="close"></div><section class="${dialog?'dialog':'drawer'+(wide?' wide':'')}" role="dialog" aria-modal="true" aria-labelledby="drawerTitle" aria-describedby="drawerDescription"><div class="drawer-header"><div class="row between"><h2 id="drawerTitle">${title}</h2>${btn('','close','close','quiet iconbtn','aria-label="Close panel"')}</div><p class="sub" id="drawerDescription">${subtitle}</p></div><div class="drawer-body">${body}</div>${footer?`<div class="drawer-footer">${footer}</div>`:''}</section>`;const form=$('#overlay form');S.drawerInitial=form?new URLSearchParams(new FormData(form)).toString():null;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay input:not([type=hidden]), #overlay select, #overlay button')?.focus(),20)}
function closeDrawer(force=false){const form=$('#overlay form'),changed=form&&S.drawerInitial!==new URLSearchParams(new FormData(form)).toString();if(!force&&changed&&!confirm('Discard your unsaved changes?'))return false;S.drawer=null;S.drawerInitial=null;$('#overlay').innerHTML='';$('#app').inert=false;document.body.style.overflow='';lastFocus?.focus();return true}
function showError(e){if(e?.status===401&&S.user){closeDrawer(true);login();toast('Your session expired. Sign in again to continue.');return}const box=$('#formError');if(box){box.className='form-error';box.setAttribute('role','alert');box.setAttribute('aria-live','assertive');box.textContent=e.message}else toast(e.message)}
async function propertyDrawer(pid){const p=project(),baseCountry=scopeHomeCountry(),baseState=isCountryScope(S.country)?'':S.state,r=p.properties.find(x=>x.id===pid)||{id:id(),name:'',code:'',country:baseCountry,state:baseState,district:'',city:'',address:'',status:'Live',team:p.team,notes:'',lat:'',lng:'',competitor:false,custom:{}};S.editing=clone(r);S.editingExisting=!!pid;S.drawer='property';await geo(r.country);drawer(pid?(canEdit()?'Edit property':'Property details'):'Add a property',h(p.name),`<form id="propertyForm"><div id="formError"></div><div class="field-grid">${field('Property name','name','text',r.name,true,'maxlength="120"')}${field('Property code','code','text',r.code,true,'maxlength="50"')}${selectField('Country','country',countryOptions(r.country),true)}${selectField('State / Province','state',options(regionNames(S.geo[r.country]),r.state,'Select a state'),true)}<div id="districtField">${districtField(r.country,r.state,propertyCity(r))}</div><div class="field full">${field('Street address','address','text',r.address)}</div>${selectField('Property status','status',options(['Live','Opportunity'],r.status),true)}${selectField('Map legend','legendId',options(projectLegends().map(x=>({value:x.id,label:x.label})),propertyLegendId(r)),true)}${selectField('Owning team','team',options(S.config.teams||[],r.team))}${field('Latitude','lat','number',r.lat,false,'min="-90" max="90" step="any" placeholder="Optional"')}${field('Longitude','lng','number',r.lng,false,'min="-180" max="180" step="any" placeholder="Optional"')}<div class="hint full">Coordinates are optional. Only entered coordinates appear as exact map locations.</div><label class="row full"><input type="checkbox" name="competitor" ${r.competitor?'checked':''}>Competitor property</label><div id="customFields" class="field-grid full">${renderCustomFields(r)}</div>${field('Notes','notes','textarea',r.notes)}</div></form>`,`${pid&&canEdit()?btn('Delete','delete-property','delete','quiet danger','data-id="'+r.id+'"'):''}<span class="spacer"></span>${btn('Cancel','close')}${canEdit()?'<button class="primary" type="submit" form="propertyForm">Save property</button>':''}`);if(!canEdit())$('#propertyForm').querySelectorAll('input,select,textarea').forEach(e=>e.disabled=true)}
function districtField(country,state,value){if(country==='USA')return selectField('City','district',options(districts(country,state),value,'Optional'),false,!state?'disabled':'');return field('City','district','text',value,false,'placeholder="Enter city (optional)"')}
function renderCustomFields(r){return getFields().filter(f=>fieldAllowed(f)&&(!f.condition||f.condition===r.status)).map(f=>customInput(f,r.custom?.[f.id]??'',!fieldAllowed(f,'editable'))).join('')}
async function submitProperty(form){const fd=new FormData(form),r={...S.editing};for(const k of ['name','code','country','state','district','address','status','team','notes','lat','lng'])r[k]=String(fd.get(k)||'').trim();r.city='';r.legendId=String(fd.get('legendId')||projectLegends()[0]?.id||'');r.competitor=fd.has('competitor');r.custom={...r.custom};getFields().forEach(f=>{if(fieldAllowed(f,'editable')&&(!f.condition||f.condition===r.status))r.custom[f.id]=f.type==='checkbox'?fd.has('custom_'+f.id):fd.get('custom_'+f.id)||''});const p=clone(project());if(p.properties.some(x=>x.id!==r.id&&x.code.toLowerCase()===r.code.toLowerCase()))throw Error('This property code already exists in the project.');if((r.lat==='')!==(r.lng===''))throw Error('Enter both latitude and longitude.');if(S.editingExisting)p.properties=p.properties.map(x=>x.id===r.id?r:x);else p.properties.push(r);await saveProject(p,S.editingExisting?'Property updated':'Property added to your project');closeDrawer(true);await render()}
function projectDrawer(pid){const p=S.projects.find(x=>x.id===pid);if(!p)return newProject();S.editingProject=pid;S.drawer='project';drawer('Project settings','Update project details or remove this project.',`<form id="projectForm" class="stack"><div id="formError"></div>${field('Project name','name','text',p.name,true,'maxlength="100"')}${field('Description','description','textarea',p.description,false,'maxlength="2000"')}${selectField('Starting country','country',countryOptions(p.country),true)}${selectField('Owning team','team',options(S.config.teams,p.team),true)}<div class="hint">Changing the starting country does not move or delete existing properties.</div></form>`,btn('Delete project','delete-project','delete','quiet danger',`data-id="${p.id}"`)+`<span class="spacer"></span>`+btn('Cancel','close')+'<button form="projectForm" class="primary">Save project</button>',false,true)}
function newProject(){S.editingProject=null;S.drawer='project';const start=scopeHomeCountry()||'USA';drawer('A new beginning','Create a project for your portfolio or next opportunity.',`<form id="projectForm" class="stack"><div id="formError"></div>${field('Project name','name','text','',true,'maxlength="100" placeholder="e.g. Northeast Expansion"')}${field('Description','description','textarea','',false,'maxlength="2000" placeholder="What is this project about?"')}${selectField('Starting country','country',countryOptions(start),true)}${selectField('Owning team','team',options(S.config.teams,S.user.team),true)}</form>`,btn('Cancel','close')+'<button form="projectForm" class="primary">Create project</button>',false,true)}
async function submitProject(form){const fd=new FormData(form);if(S.editingProject){const p=clone(S.projects.find(x=>x.id===S.editingProject));p.name=fd.get('name').trim();p.description=fd.get('description').trim();p.team=fd.get('team');p.country=fd.get('country');const saved=await saveProject(p,'Project updated');if(S.project===saved.id)S.country=saved.country;closeDrawer(true);S.view='projects';return render()}const palette=clone(S.config.palette||paletteFrom(PRESETS.Classic)),p={name:fd.get('name').trim(),description:fd.get('description').trim(),team:fd.get('team'),country:fd.get('country'),palette,legends:defaultLegends(palette),fields:[],regionRules:{},properties:[],exports:[],demo:false};const saved=await api('/api/projects','POST',p);S.projects.push(saved);S.project=saved.id;S.country=saved.country;S.state='';S.district='';S.search='';S.view='workspace';closeDrawer(true);toast('Your new project is ready');await render()}
function colorsDrawer(){S.drawer='colors';S.colorDraft=clone(normalizePalette(project().palette));S.generated=null;drawer('Color studio','Make your map feel like your own.',`<div id="formError"></div><div class="section-title">01 / Preset palettes</div><div class="palette-cards">${Object.entries(PRESETS).map(([n,a])=>`<button class="palette-card" data-action="preset" data-preset="${n}"><span>${n}</span><div class="swatches">${a.map(c=>`<span style="background:${c}"></span>`).join('')}</div></button>`).join('')}</div><div class="section-title">02 / Generate a palette</div><label class="field"><span>Describe a mood</span><input id="palettePrompt" placeholder="Calm ocean, warm earth, vibrant…"><small>Generated locally using color harmony rules. No AI service connected.</small></label><div class="row field-gap">${btn('Generate palette','generate-palette','auto_awesome','small')}</div><div id="generatedPalette"></div><div class="section-title row between">03 / Custom colors ${btn('Reset','reset-colors','','quiet small')}</div><div id="colorInputs">${colorInputs()}</div><div class="hint">Category labels stay unchanged when you change colors. The palette is included in PNG and PDF exports.</div><div class="section-title">Save palette to</div><select id="paletteScope" aria-label="Palette scope">${options([{value:'project',label:'This project'},{value:'account',label:'Account default + this project'}],'project')}</select>`,btn('Cancel','close')+btn('Apply colors','apply-colors','check','primary',!canEdit()?'disabled':''))}
function colorInputs(){return COLOR_KEYS.map(k=>`<div class="color-row"><span>${k==='Live'?'Live properties':k}</span><input type="color" data-color="${k}" value="${S.colorDraft[k]}" aria-label="${k} color"><input type="text" data-hex="${k}" value="${S.colorDraft[k]}" aria-label="${k} hex code" pattern="#[0-9a-fA-F]{6}"></div>`).join('')}
function generatePalette(){const prompt=$('#palettePrompt').value.toLowerCase();let hue=/ocean|blue|calm|cool/.test(prompt)?210:/earth|forest|green|natural/.test(prompt)?130:/warm|sun|orange/.test(prompt)?28:/pink|rose/.test(prompt)?330:/purple|violet/.test(prompt)?270:Math.random()*360;hue+=Math.random()*18-9;const c=(h,s,l)=>d3.hsl(h,s,l).formatHex();S.generated=[c(hue,.48,.49),c(hue+65,.43,.45),c(hue+175,.58,.51),'#cfd5df',c(hue+115,.35,.59)];$('#generatedPalette').innerHTML=`<div class="generated"><small>YOUR GENERATED PALETTE</small><div class="row"><div class="swatches grow">${S.generated.map(c=>`<span style="background:${c}"></span>`).join('')}</div>${btn('Use palette','use-generated','','small')}</div></div>`}
function refreshColorInputs(){$('#colorInputs').innerHTML=colorInputs()}
function scopedFields(){if(S.fieldScope==='account')return S.config.fields||[];if(S.fieldScope==='team')return S.config.teamFields?.[project()?.team]||[];return project()?.fields||[]}
function settingsView(){const isAdmin=S.user.role==='admin';let body='';if(S.settingsTab==='fields'){body=`<div class="settings-grid"><section class="panel"><div class="panelhead"><div><h3>Property fields</h3><p class="sub">Flexible forms, consistent data.</p></div>${btn('Add field','add-field','add','primary small',!isAdmin?'disabled':'')}</div><div class="toolbar"><label>CONFIGURATION SCOPE<select id="fieldScope">${options([{value:'account',label:'Workspace defaults'},{value:'team',label:'Team: '+(project()?.team||'No project')},{value:'project',label:'Project: '+(project()?.name||'No project')}],S.fieldScope)}</select></label><span class="badge">${isAdmin?'Admin':'Read only'}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>FIELD</th><th>TYPE</th><th>REQUIRED</th><th>VISIBLE TO</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${['Property name','Property code','Country','State / Province'].map(n=>`<tr><td><strong>${n}</strong></td><td>${n.includes('Country')||n.includes('State')?'Location':'Text'}</td><td>${icon('check')}</td><td>Everyone</td><td>${icon('lock')}</td></tr>`).join('')}${scopedFields().map(f=>`<tr><td><strong>${h(f.label)}</strong></td><td>${h(f.type)}</td><td>${f.required?icon('check'):'Optional'}</td><td>${h(f.visibility||'everyone')}</td><td>${btn('','edit-field','edit','quiet iconbtn',`data-id="${f.id}" aria-label="Edit ${h(f.label)}" ${!isAdmin?'disabled':''}`)}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><div class="hint">Workspace defaults → Team settings → Project overrides.<br>Required core fields and locked account fields stay protected.</div></div></section><aside class="panel form-preview" aria-label="Form preview"><div class="row between"><h3>Form preview</h3><span class="badge">Admin</span></div><p class="sub block-gap">${h(project()?.name||'New project')}</p><div class="stack">${field('Property name','preview_name','text','Aria',true,'disabled')}${field('Property code','preview_code','text','V227',true,'disabled')}${getFields().map(f=>customInput(f,'',true)).join('')}${!getFields().length?'<p class="sub">Custom fields will appear here.</p>':''}</div></aside></div>`}else if(S.settingsTab==='account')body=`<section class="panel narrow"><div class="panelhead"><h3>Teams</h3></div><form id="teamForm" class="stack panel-body"><div id="formError"></div>${field('Teams (one per line)','teams','textarea',S.config.teams.join('\n'),true)}<button class="primary start" ${!isAdmin?'disabled':''}>Save teams</button></form></section>`;else body=`<section class="panel narrow"><div class="panelhead"><h3>Your data, in your hands</h3></div><div class="stack panel-body"><p class="sub">Download a portable JSON backup of the projects and fields you can access. Exported PNG/PDF files are downloaded separately.</p><div class="row">${btn('Download backup','backup','download')}${btn('Import project backup','import','folder')}</div><input id="importFile" type="file" accept=".json,application/json" hidden><div class="hint">Imports create new projects, leaving existing work intact. Geographic data is bundled for offline use. District boundaries are currently bundled for the United States; other countries support manual district entry.</div></div></section>`;return header('WORKSPACE SETTINGS','Workspace configuration','Manage fields, teams, legends, and workspace data.')+`<div class="settings-tabs">${['fields','account','data'].map((t,i)=>btn(['Property fields','Teams','Data & backups'][i],'settings-tab','',S.settingsTab===t?'active':'',`data-tab="${t}"`)).join('')}</div>`+body}
function fieldDrawer(fid){const f=scopedFields().find(x=>x.id===fid)||{id:id().replaceAll('-','').slice(0,16),label:'',type:'text',required:false,visibility:'everyone',editable:'everyone',options:[],condition:'',locked:false};S.fieldDraft=clone(f);S.drawer='field';drawer(fid?'Edit field':'Add a custom field',`Scope: ${h(S.fieldScope==='account'?'Workspace defaults':S.fieldScope==='team'?project().team:project().name)}`,`<form id="fieldForm" class="stack"><div id="formError"></div>${field('Field label','label','text',f.label,true,'maxlength="80" placeholder="e.g. Site capacity"')}${selectField('Field type','type',options(['text','number','date','select','checkbox'],f.type),true)}${field('Dropdown options (one per line)','options','textarea',f.options.join('\n'))}<div class="field-grid">${selectField('Visible to','visibility',options(['everyone','contributors','admins'],f.visibility))}${selectField('Editable by','editable',options(['everyone','contributors','admins'],f.editable))}</div>${selectField('Show when property status is','condition',options(['Live','Opportunity'],f.condition,'Always'))}<label class="row"><input type="checkbox" name="required" ${f.required?'checked':''}>Required field</label>${S.fieldScope==='account'?`<label class="row"><input type="checkbox" name="locked" ${f.locked?'checked':''}>Lock for teams and projects</label>`:''}<div class="hint">Required fields must be editable by the roles that can see them. Existing values are preserved when a field is hidden.</div></form>`,`${fid?btn('Remove field','remove-field','delete','quiet danger',`data-id="${f.id}"`):''}<span class="spacer"></span>${btn('Cancel','close')}<button form="fieldForm" class="primary">Save field</button>`)}
async function saveFieldList(fs){if(S.fieldScope==='project'){const p=clone(project());p.fields=fs;await saveProject(p,'Field configuration saved')}else{const cfg=clone(S.config);if(S.fieldScope==='account')cfg.fields=fs;else{cfg.teamFields??={};cfg.teamFields[project().team]=fs}await api('/api/config','PUT',cfg);S.config=cfg;toast('Field configuration saved')}closeDrawer(true);await render()}
function teamView(){return header('PEOPLE & PERMISSIONS','Local accounts','Manage private workspaces and access stored in this computer’s SQLite database.',btn('Add account','add-user','person_add','primary'))+`<div class="hint block-gap">Every new account receives a private workspace. The fixed email domain is @igt.com; no invitation email is sent.</div><section class="panel"><div class="panelhead"><h3>Workspace accounts</h3><span class="badge">${h(S.config.accountName)}</span></div><div id="userList"><div class="empty">Loading accounts…</div></div></section><section class="panel properties-panel"><div class="panelhead"><h3>Project access</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>PROJECT</th><th>TEAM</th><th>YOUR ACCESS</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${S.projects.map(p=>`<tr><td><strong>${h(p.name)}</strong>${p.personal?'<small class="block sub">Personal workspace</small>':''}</td><td>${h(p.team)}</td><td>${h(access(p))}</td><td>${btn('Manage access','share','group','small',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`}
async function loadUsers(){try{S.users=await api('/api/users');const el=$('#userList');if(el)el.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>EMAIL</th><th>DESIGNATION</th><th>DEPARTMENT</th><th>ROLE</th><th>STATUS</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${S.users.map(u=>`<tr><td><strong>${h(u.name)}</strong></td><td>${h(u.email)}</td><td>${h(u.designation)}</td><td>${h(u.department)}</td><td>${h(u.role)}</td><td><span class="badge ${u.active?'':'muted'}">${u.active?'Active':'Inactive'}</span></td><td>${btn('Edit','edit-user','edit','quiet small',`data-id="${u.id}"`)}</td></tr>`).join('')}</tbody></table></div>`}catch(e){if($('#userList'))$('#userList').innerHTML=`<div class="empty">${h(e.message)}</div>`}}
