 $('#exportLayoutHint').textContent=pdf?'A map page followed by a table with one full row per property, optionally in a section per state. Best for sharing as a document.':context.showOverview?'One 16:9 image with the map and the same portfolio overview used on the PDF cover page.':'Always one image. The map and property list resize to share a 16:9 slide; a very long list makes the image taller rather than splitting it.';
 $('#exportButton').textContent=pdf?'Download PDF':'Download PNG';
